import { afterEach, describe, expect, it, vi } from "vitest";
import { buildSeed } from "../src/data/seed";
import { askAssistant, quickAnswer, toolFindProviders, toolGetHelp, toolMyBookings, guardText } from "../src/ai/assistant";
import type { LlmSettings } from "../src/ai/adapter";
// @ts-expect-error plain JS module generated by scripts/build-worker.ts
import worker from "../worker/worker.js";

const ctxFor = (userId: string) => {
  const s = buildSeed();
  const me = s.users.find((u) => u.id === userId)!;
  return { s, me };
};
const proxy: LlmSettings = { provider: "proxy", model: "", apiKey: "", proxyUrl: "https://ai.test" };

/** Fakes the AI server: returns the given model turns in order and records what the app sent. */
function fakeServer(turns: object[]) {
  const sent: any[] = [];
  let i = 0;
  vi.stubGlobal("fetch", vi.fn(async (_url: string, init: RequestInit) => {
    sent.push(JSON.parse(String(init.body)));
    const content = turns[Math.min(i++, turns.length - 1)];
    return new Response(JSON.stringify({ content }), { status: 200, headers: { "Content-Type": "application/json" } });
  }));
  return sent;
}
afterEach(() => vi.unstubAllGlobals());

describe("assistant tools run on the app's own data", () => {
  it("find_providers uses the real ranked search for the resident", () => {
    const ctx = ctxFor("u-tan");
    const r = toolFindProviders(ctx, { need: "pipe leaking", category_id: "plumbing" });
    expect(r.finding?.categoryId).toBe("plumbing");
    expect(r.finding!.results.length).toBeGreaterThan(0);
    expect((r.response.providers as any[])[0].name).toBe(r.finding!.results[0].provider.displayName);
  });
  it("find_providers falls back to keywords when the AI gives no category", () => {
    const r = toolFindProviders(ctxFor("u-aisyah"), { need: "aircond bocor air" });
    expect(r.finding?.categoryId).toBe("aircond");
  });
  it("find_providers rejects invented category ids", () => {
    const r = toolFindProviders(ctxFor("u-aisyah"), { need: "zzz qqq", category_id: "spaceship-repair" });
    expect(r.finding).toBeUndefined();
    expect(r.response.providers).toEqual([]);
  });
  it("get_help only returns known topics", () => {
    expect(toolGetHelp({ topic: "request_board" }).help?.title).toBe("The request board");
    expect(toolGetHelp({ topic: "make_up_a_rule" }).help).toBeUndefined();
  });
  it("my_bookings lists only this resident's bookings", () => {
    const ctx = ctxFor("u-aisyah");
    const r = toolMyBookings(ctx);
    expect(r.bookings.length).toBeGreaterThan(0);
    const ids = new Set(ctx.s.bookings.filter((b) => b.residentId === "u-aisyah").map((b) => b.id));
    expect(r.bookings.every((b) => ids.has(b.id))).toBe(true);
  });
  it("guard drops wording that names a provider the tools didn't return", () => {
    const ctx = ctxFor("u-tan");
    expect(guardText("Try Shine Pro Cleaning, they're great", ctx, new Set())).toBe("Here's what I found on JiranLink:");
    expect(guardText("Ravi can help", ctx, new Set())).toBe("Ravi can help");
  });
});

describe("assistant loop with the AI server", () => {
  it("runs the tool the AI asks for, sends the result back verbatim, then shows cards", async () => {
    const sent = fakeServer([
      { role: "model", parts: [{ functionCall: { name: "find_providers", args: { need: "fix the pipes", category_id: "plumbing" } }, thoughtSignature: "sig-1" }] },
      { role: "model", parts: [{ text: "These plumbers are near you in Taman Melawati." }] },
    ]);
    const ctx = ctxFor("u-tan");
    const r = await askAssistant("I want someone to fix the pipes, who can do it?", [], ctx, proxy);
    expect(r.mode).toBe("ai");
    expect(r.toolCalls.map((t) => t.name)).toEqual(["find_providers"]);
    expect(r.providers?.results.length).toBeGreaterThan(0);
    expect(r.text).toContain("plumbers");
    // Second call carries the model's function call (with its signature) and our function response.
    const second = sent[1].contents;
    expect(second.at(-2).parts[0].thoughtSignature).toBe("sig-1");
    expect(second.at(-1).parts[0].functionResponse.name).toBe("find_providers");
    expect(r.history).toHaveLength(2);
  });
  it("help answers carry buttons from the help guide", async () => {
    fakeServer([
      { role: "model", parts: [{ functionCall: { name: "get_help", args: { topic: "request_board" } } }] },
      { role: "model", parts: [{ text: "Post it on the request board and neighbours can reply." }] },
    ]);
    const r = await askAssistant("how do i ask for a skill not listed", [], ctxFor("u-aisyah"), proxy);
    expect(r.help?.actions[0].route).toEqual({ name: "requests" });
  });
  it("falls back to a quick keyword answer when the AI server fails", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => new Response(JSON.stringify({ error: "Too many questions" }), { status: 429 })));
    const r = await askAssistant("aircond bocor air", [], ctxFor("u-aisyah"), proxy);
    expect(r.mode).toBe("quick");
    expect(r.note).toMatch(/Too many questions/);
    expect(r.providers?.categoryId).toBe("aircond");
  });
  it("stops after 4 rounds even if the AI keeps calling tools", async () => {
    const sent = fakeServer([{ role: "model", parts: [{ functionCall: { name: "my_bookings", args: {} } }] }]);
    const r = await askAssistant("bookings?", [], ctxFor("u-aisyah"), proxy);
    expect(sent.length).toBe(4);
    expect(r.text).toBeTruthy();
  });
});

describe("quick answers without AI", () => {
  const ctx = ctxFor("u-aisyah");
  it("how-to questions go to the help guide", () => {
    expect(quickAnswer("how do I cancel a booking?", ctx).help?.topic).toBe("cancelling");
    expect(quickAnswer("macam mana nak bayar lepas siap", ctx).help?.topic).toBe("pay_after_rule");
  });
  it("needs go to provider search", () => {
    expect(quickAnswer("sinki tersumbat", ctx).providers?.categoryId).toBe("plumbing");
  });
  it("my bookings", () => {
    expect(quickAnswer("what's the status of my bookings", ctx).bookings).toBeDefined();
  });
  it("unmatched needs offer a request-board draft", () => {
    expect(quickAnswer("zzkx blorp", ctx).draft).toBe("zzkx blorp");
  });
});

describe("AI server (worker/worker.js)", () => {
  const env = { GEMINI_API_KEY: "secret-key" };
  const req = (path: string, body?: unknown, origin = "https://hengchuanquah.github.io", ip = "1.1.1.1") =>
    new Request(`https://w.test${path}`, {
      method: body === undefined ? "GET" : "POST",
      headers: { Origin: origin, "Content-Type": "application/json", "CF-Connecting-IP": ip },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  const gemini = (status: number, data: object) => new Response(JSON.stringify(data), { status });
  const ok = { candidates: [{ content: { parts: [{ text: '{"categories":[{"id":"plumbing","score":0.9}]}' }] } }] };

  it("puts the key in a header, never in the reply, and adds the prompt server-side", async () => {
    const f = vi.fn(async () => gemini(200, ok));
    vi.stubGlobal("fetch", f);
    const res = await worker.fetch(req("/classify", { text: "paip bocor" }, undefined, "2.2.2.1"), env);
    expect(res.status).toBe(200);
    const [, init] = f.mock.calls[0] as unknown as [string, RequestInit];
    expect((init.headers as Record<string, string>)["x-goog-api-key"]).toBe("secret-key");
    expect(JSON.parse(String(init.body)).systemInstruction.parts[0].text).toMatch(/classify/);
    expect(await res.text()).not.toContain("secret-key");
  });
  it("refuses other websites", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => gemini(200, ok)));
    const res = await worker.fetch(req("/classify", { text: "x" }, "https://evil.example", "2.2.2.2"), env);
    expect(res.status).toBe(403);
  });
  it("tries the fallback model when the default is unavailable", async () => {
    const f = vi.fn().mockResolvedValueOnce(gemini(404, { error: { message: "model not found" } })).mockResolvedValueOnce(gemini(200, ok));
    vi.stubGlobal("fetch", f);
    const res = await worker.fetch(req("/classify", { text: "paip" }, undefined, "2.2.2.3"), env);
    expect(res.status).toBe(200);
    expect(String(f.mock.calls[1][0])).toContain("flash-lite");
  });
  it("only forwards allowed fields to Gemini and caps message length", async () => {
    const f = vi.fn(async () => gemini(200, { candidates: [{ content: { parts: [{ text: "hi" }] } }] }));
    vi.stubGlobal("fetch", f);
    await worker.fetch(req("/agent", { contents: [{ role: "user", parts: [{ text: "hello", evil: "x" }] }] }, undefined, "2.2.2.4"), env);
    const sentBody = JSON.parse(String((f.mock.calls[0] as unknown as [string, RequestInit])[1].body));
    expect(sentBody.contents[0].parts[0]).toEqual({ text: "hello" });
    expect(sentBody.tools[0].functionDeclarations.map((t: { name: string }) => t.name)).toContain("find_providers");
    const long = await worker.fetch(req("/agent", { contents: [{ role: "user", parts: [{ text: "x".repeat(700) }] }] }, undefined, "2.2.2.4"), env);
    expect(long.status).toBe(400);
  });
  it("rate-limits one visitor", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => gemini(200, ok)));
    let last = 200;
    for (let i = 0; i < 61; i++) last = (await worker.fetch(req("/classify", { text: "paip" }, undefined, "9.9.9.9"), env)).status;
    expect(last).toBe(429);
  });
  it("answers CORS preflight", async () => {
    const res = await worker.fetch(new Request("https://w.test/agent", { method: "OPTIONS", headers: { Origin: "https://hengchuanquah.github.io" } }), env);
    expect(res.status).toBe(204);
    expect(res.headers.get("Access-Control-Allow-Origin")).toBe("https://hengchuanquah.github.io");
  });
});

describe("AI server on Vercel (api/*.js)", () => {
  it("routes /api/classify through the same handler with the key from process.env", async () => {
    // @ts-expect-error plain JS module generated by scripts/build-worker.ts
    const { POST } = await import("../api/classify.js");
    const f = vi.fn(async () => new Response(JSON.stringify({ candidates: [{ content: { parts: [{ text: "{}" }] } }] }), { status: 200 }));
    vi.stubGlobal("fetch", f);
    process.env.GEMINI_API_KEY = "vercel-key";
    const res = await POST(new Request("https://x.vercel.app/api/classify", {
      method: "POST",
      headers: { Origin: "https://hengchuanquah.github.io", "x-forwarded-for": "3.3.3.3", "Content-Type": "application/json" },
      body: JSON.stringify({ text: "paip bocor" }),
    }));
    expect(res.status).toBe(200);
    expect(((f.mock.calls[0] as unknown as [string, RequestInit])[1].headers as Record<string, string>)["x-goog-api-key"]).toBe("vercel-key");
    delete process.env.GEMINI_API_KEY;
  });
});

describe("AI server handles a busy model", () => {
  it("retries once, then falls back to the lighter model", async () => {
    // @ts-expect-error plain JS module
    const { handle } = await import("../api/_core.js");
    const busy = () => new Response(JSON.stringify({ error: { message: "high demand" } }), { status: 503 });
    const good = () => new Response(JSON.stringify({ candidates: [{ content: { parts: [{ text: "{}" }] } }] }), { status: 200 });
    const f = vi.fn().mockImplementationOnce(async () => busy()).mockImplementationOnce(async () => busy()).mockImplementation(async () => good());
    vi.stubGlobal("fetch", f);
    const res = await handle(new Request("https://x/api/check", { headers: { "x-forwarded-for": "4.4.4.4" } }), { GEMINI_API_KEY: "k" });
    const body = await res.json();
    expect(res.status).toBe(200);
    expect(f).toHaveBeenCalledTimes(3);
    expect(body.model).toContain("flash-lite");
  });
});
